<?php
$active_menu='hr_letters';$active_submenu='letters';include 'header.php';require_once __DIR__.'/../foundation.php';require_once __DIR__.'/../hr_letters.php';oecrm_require_permission($conn,'hr_letters','view');$companyId=oecrm_current_company_id($conn);$employees=mysqli_query($conn,'SELECT id,employeeCode,name,designation,companyEmail FROM employeestbl WHERE company_id='.(int)$companyId.' AND status=0 ORDER BY name');$templates=mysqli_query($conn,'SELECT id,letter_type,name,subject,body_html FROM hr_letter_templates WHERE company_id='.(int)$companyId.' AND status=1 ORDER BY letter_type,is_default DESC,name');$templateRows=[];while($t=mysqli_fetch_assoc($templates))$templateRows[]=$t;$type=trim($_GET['type']??'');$employeeId=(int)($_GET['employee_id']??0);$where='l.company_id=?';$types='i';$params=[$companyId];if(isset(oecrm_letter_types()[$type])){$where.=' AND l.letter_type=?';$types.='s';$params[]=$type;}if($employeeId){$where.=' AND l.employee_id=?';$types.='i';$params[]=$employeeId;}$sql='SELECT l.*,e.name employee_name,e.employeeCode,(SELECT delivery_status FROM hr_letter_delivery_logs d WHERE d.letter_id=l.id ORDER BY d.id DESC LIMIT 1) delivery_status FROM hr_letters l JOIN employeestbl e ON e.id=l.employee_id WHERE '.$where.' ORDER BY l.id DESC LIMIT 300';$stmt=mysqli_prepare($conn,$sql);mysqli_stmt_bind_param($stmt,$types,...$params);mysqli_stmt_execute($stmt);$letters=mysqli_stmt_get_result($stmt);$flash=$_SESSION['letter_flash']??'';$error=$_SESSION['letter_error']??'';unset($_SESSION['letter_flash'],$_SESSION['letter_error']);
?>
<div id="page-wrapper" class="compact-admin-page letter-admin-page"><?php if($flash):?><div class="alert alert-success"><?php echo oecrm_h($flash);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo oecrm_h($error);?></div><?php endif;?><div class="panel panel-default"><div class="panel-heading foundation-heading"><span>Create HR Letter</span><small>Employee details and company branding are filled automatically</small></div><div class="panel-body"><form method="post" action="hrLetterAction.php" class="letter-form"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="create_letter"><div class="letter-form-grid three"><div class="form-group"><label>Employee</label><select name="employee_id" class="form-control" required><option value="">Select employee</option><?php mysqli_data_seek($employees,0);while($e=mysqli_fetch_assoc($employees)):?><option value="<?php echo (int)$e['id'];?>"><?php echo oecrm_h($e['employeeCode'].' - '.$e['name'].' - '.$e['designation']);?></option><?php endwhile;?></select></div><div class="form-group"><label>Letter Type</label><select name="letter_type" id="letterType" class="form-control" required><option value="">Select type</option><?php foreach(oecrm_letter_types() as $key=>$label):?><option value="<?php echo $key;?>"><?php echo $label;?></option><?php endforeach;?></select></div><div class="form-group"><label>Template</label><select name="template_id" id="letterTemplate" class="form-control" required><option value="">Select template</option><?php foreach($templateRows as $t):?><option value="<?php echo (int)$t['id'];?>" data-type="<?php echo $t['letter_type'];?>" data-subject="<?php echo oecrm_h($t['subject']);?>" data-body="<?php echo oecrm_h($t['body_html']);?>"><?php echo oecrm_h($t['name']);?></option><?php endforeach;?></select></div></div><div class="letter-form-grid"><div class="form-group"><label>Issue Date</label><input type="date" name="issue_date" class="form-control" value="<?php echo date('Y-m-d');?>" required></div><div class="form-group"><label>Subject</label><input name="subject" id="letterSubject" class="form-control" required></div></div><div class="form-group"><label>Letter Content</label><textarea name="body_html" id="letterBody" class="form-control letter-editor" required></textarea></div><div class="token-help"><strong>Additional optional tokens</strong><span>{{new_designation}}</span><span>{{effective_date}}</span><span>{{revised_salary}}</span><span>{{previous_from}}</span><span>{{previous_to}}</span><span>{{continuation_from}}</span><span>{{continuation_to}}</span><span>{{term_no}}</span><span>{{last_working_date}}</span><span>{{reason}}</span></div><div class="letter-form-grid three"><input class="form-control" name="new_designation" placeholder="New designation"><input class="form-control" name="effective_date" placeholder="Effective date"><input class="form-control" name="revised_salary" placeholder="Revised salary"></div><div class="letter-form-grid"><input class="form-control" name="last_working_date" placeholder="Last working date"><input class="form-control" name="reason" placeholder="Reason / remarks"></div><button class="btn btn-primary"><i class="fa fa-file-text-o"></i> Create Draft</button></form></div></div><div class="panel panel-default"><div class="panel-heading">Letter History</div><div class="panel-body"><form method="get" class="letter-filters"><select name="type" class="form-control"><option value="">All types</option><?php foreach(oecrm_letter_types() as $key=>$label):?><option value="<?php echo $key;?>" <?php echo $type===$key?'selected':'';?>><?php echo $label;?></option><?php endforeach;?></select><select name="employee_id" class="form-control"><option value="0">All employees</option><?php mysqli_data_seek($employees,0);while($e=mysqli_fetch_assoc($employees)):?><option value="<?php echo (int)$e['id'];?>" <?php echo $employeeId===(int)$e['id']?'selected':'';?>><?php echo oecrm_h($e['name']);?></option><?php endwhile;?></select><button class="btn btn-default"><i class="fa fa-filter"></i> Filter</button></form><div class="table-responsive"><table class="table foundation-table"><thead><tr><th>Reference</th><th>Employee</th><th>Letter</th><th>Date</th><th>Status</th><th>Delivery</th><th>Actions</th></tr></thead><tbody><?php if(mysqli_num_rows($letters)===0):?><tr><td colspan="7" class="empty-cell">No letters found.</td></tr><?php endif;?><?php while($l=mysqli_fetch_assoc($letters)):?><tr><td><strong><?php echo oecrm_h($l['reference_no']);?></strong></td><td><?php echo oecrm_h($l['employee_name']);?><small><?php echo oecrm_h($l['employeeCode']);?></small></td><td><?php echo oecrm_h(oecrm_letter_types()[$l['letter_type']]??$l['letter_type']);?><small><?php echo oecrm_h($l['subject']);?></small></td><td><?php echo date('d M Y',strtotime($l['issue_date']));?></td><td><span class="letter-status <?php echo $l['status'];?>"><?php echo ucfirst($l['status']);?></span></td><td><?php echo oecrm_h($l['delivery_status']?:'Not sent');?></td><td class="letter-actions"><a class="icon-action" target="_blank" href="hrLetterView.php?id=<?php echo (int)$l['id'];?>" title="View / PDF"><i class="fa fa-file-pdf-o"></i></a><?php if($l['status']==='draft'&&oecrm_can($conn,'hr_letters','issue')):?><form method="post" action="hrLetterAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="issue"><input type="hidden" name="id" value="<?php echo (int)$l['id'];?>"><button class="icon-action approve" title="Issue"><i class="fa fa-check"></i></button></form><?php endif;?><?php if(in_array($l['status'],['issued','emailed'],true)&&oecrm_can($conn,'hr_letters','email')):?><form method="post" action="hrLetterAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="email"><input type="hidden" name="id" value="<?php echo (int)$l['id'];?>"><button class="icon-action" title="Email"><i class="fa fa-envelope"></i></button></form><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div></div></div><script>(function(){var type=document.getElementById('letterType'),tpl=document.getElementById('letterTemplate'),subject=document.getElementById('letterSubject'),body=document.getElementById('letterBody');function filter(){Array.prototype.forEach.call(tpl.options,function(o){if(!o.value)return;o.hidden=o.dataset.type!==type.value;});tpl.value='';}type.addEventListener('change',filter);tpl.addEventListener('change',function(){var o=tpl.options[tpl.selectedIndex];subject.value=o.dataset.subject||'';body.value=o.dataset.body||'';});})();</script><?php include 'footer.php';?>

